<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;

class BillingOrder extends Model
{
    public $incrementing = false;

    protected $keyType = 'string';

    // UUID is generated by the domain service, not by an auto-increment column.
    protected $guarded = [];

    protected $hidden = ['idempotency_hash', 'request_hash', 'checkout_url'];

    protected function casts(): array
    {
        return ['offer_snapshot' => 'array', 'expires_at' => 'immutable_datetime', 'fulfilled_at' => 'immutable_datetime'];
    }
}
